                        return withUnsafeTemporaryAllocation(of: SIMD<Int16>.self, capacity: 1) {
                            result in
                            unsafe portLookup8I16InVectorCode(
                                result.baseAddress.unsafelyUnwrapped,
                                at: &indices,
